def Hom.mk' {A B : AbelianVariety K} (f : A.toOver ⟶ B.toOver)
    (one_f : η[A.toOver] ≫ f = η[B.toOver] := by cat_disch)
    (mul_f : μ[A.toOver] ≫ f = (f ⊗ₘ f) ≫ μ[B.toOver] := by cat_disch) : A ⟶ B

lemma hom_ext {A B C : AbelianVariety K} {f g : C ⟶ prod A B}
    (hfst : f ≫ fst A B = g ≫ fst A B)
    (hsnd : f ≫ snd A B = g ≫ snd A B) : f = g

lemma closure_image_mem_irreducibleComponents {α β : Type*}
    [TopologicalSpace α] [TopologicalSpace β]
    {f : α → β} (hf : IsOpenEmbedding f) {c : Set α}
    (hc : c ∈ irreducibleComponents α) :
    closure (f '' c) ∈ irreducibleComponents β

def minimalPrimesEquivMinimalPrimesLe {R : Type*} [CommRing R] (p : PrimeSpectrum R)
    (S : Submonoid R) (A : Type*) [CommRing A] [Algebra R A] [IsLocalization S A]
    (hS : S = p.asIdeal.primeCompl) :
    minimalPrimes A ≃ { q : minimalPrimes R // q.val ≤ p.asIdeal }

theorem relativeDegree_ofPoint_of_section (hs : s ≫ f = 𝟙 S) {y : S}
    {x₀ : CodimensionOnePoint X} (hx₀ : (x₀ : X) = s y) :
    SchemeWeilDivisor.relativeDegree f (WeilDivisor.ofPoint x₀) = 1

theorem relativeDegree_zsmul_ofPoint_of_section (hs : s ≫ f = 𝟙 S) {y : S}
    {x₀ : CodimensionOnePoint X} (hx₀ : (x₀ : X) = s y) (d : ℤ) :
    SchemeWeilDivisor.relativeDegree f (d • WeilDivisor.ofPoint x₀) = d

def weightedAbelJacobiQuotientClass (w : X → ℤ) {x₀ : X} (hx₀ : w x₀ = 1) :
    WeilDivisor X →+
      weightedDegreeZeroSubgroup w ⧸ S.principalSubgroupOfWeightedDegreeZero w

lemma IsEffective.weightedDegree_eq_zero_iff_of_pos_on_support {w : X → ℤ}
    {D : WeilDivisor X} (hD : IsEffective D) (hw : ∀ x ∈ D.support, 0 < w x) :
    weightedDegree w D = 0 ↔ D = 0

lemma IsEffective.eq_zero_of_weightedDegree_eq_zero_of_pos_on_support {w : X → ℤ}
    {D : WeilDivisor X} (hD : IsEffective D) (hw : ∀ x ∈ D.support, 0 < w x)
    (hdeg : weightedDegree w D = 0) : D = 0

lemma weightedPointBaseDifference_mem_weightedDegreeZeroSubgroup {w : X → ℤ} {x₀ : X}
    (hx₀ : w x₀ = 1) (x : X) :
    weightedPointBaseDifference w x₀ x ∈ weightedDegreeZeroSubgroup w

def pushforwardWeightedDegreeZero (wX : X → ℤ) (wY : Y → ℤ) (f : X → Y)
    (hw : ∀ x, wY (f x) = wX x) :
    weightedDegreeZeroSubgroup wX →+ weightedDegreeZeroSubgroup wY

lemma le_inf {F : WeilDivisor X} {D : EffectiveDivisorOfDegree X d}
    {E : EffectiveDivisorOfDegree X e} (hFD : F ≤ D) (hFE : F ≤ E) :
    F ≤ inf D E

lemma inf_eq_left {D : EffectiveDivisorOfDegree X d}
    {E : EffectiveDivisorOfDegree X e} :
    (inf D E : WeilDivisor X) = D ↔ (D : WeilDivisor X) ≤ E

lemma inf_eq_right {D : EffectiveDivisorOfDegree X d}
    {E : EffectiveDivisorOfDegree X e} :
    (inf D E : WeilDivisor X) = E ↔ (E : WeilDivisor X) ≤ D

lemma isEffective_principalDivisor_of_integral {r : R} {u : Kˣ}
    (hu : (u : K) = algebraMap R K r) :
    IsEffective ((OrderSystem.ofDedekindDomain R K).principalDivisor (Additive.ofMul u))

def classGroupQuotientPicZeroEquivDegreeRange (w : X → ℤ)
    (h : S.IsWeightedDegreeZero w) :
    S.ClassGroup ⧸ picZero w h ≃+ (weightedDegreeClass w h).range

def classGroupQuotientPicZeroEquivInt (w : X → ℤ)
    (h : S.IsWeightedDegreeZero w)
    (hsurj : Function.Surjective (weightedDegreeClass w h)) : S.ClassGroup ⧸ picZero w h ≃+ ℤ

def classGroupQuotientPicZeroEquivIntOfWeightOne (w : X → ℤ)
    (h : S.IsWeightedDegreeZero w) {x₀ : X} (hx₀ : w x₀ = 1) :
    S.ClassGroup ⧸ picZero w h ≃+ ℤ

lemma weightedDegree_le_of_le_of_nonneg_on_support {w : X → ℤ} {D E : WeilDivisor X}
    (hDE : D ≤ E) (hw : ∀ x ∈ (E - D).support, 0 ≤ w x) :
    weightedDegree w D ≤ weightedDegree w E

lemma weightedDegree_lt_of_le_of_ne_of_pos_on_support {w : X → ℤ} {D E : WeilDivisor X}
    (hDE : D ≤ E) (hne : D ≠ E) (hw : ∀ x ∈ (E - D).support, 0 < w x) :
    weightedDegree w D < weightedDegree w E

lemma eq_of_le_of_weightedDegree_eq_of_pos_on_support {w : X → ℤ} {D E : WeilDivisor X}
    (hDE : D ≤ E) (hdeg : weightedDegree w D = weightedDegree w E)
    (hw : ∀ x ∈ (E - D).support, 0 < w x) : D = E

def classGroupAddEquivPicZeroProdInt (w : X → ℤ) (h : S.IsWeightedDegreeZero w)
    {x₀ : X} (hx₀ : w x₀ = 1) :
    S.ClassGroup ≃+ picZero w h × ℤ

lemma eq_sum_zsmul_weightedPointBaseDifference (w : X → ℤ) {D : WeilDivisor X}
    (hD : weightedDegree w D = 0) (x₀ : X) :
    D = D.sum fun x n => n • weightedPointBaseDifference w x₀ x

def integralFractionalIdealDivisorAddEquiv :
    integralFractionalIdealSubmonoid R K ≃+
      effectiveSubmonoid (HeightOneSpectrum R)

lemma add_mem_completeLinearSystem {D D' E E' : WeilDivisor X}
    (hE : E ∈ S.completeLinearSystem D) (hE' : E' ∈ S.completeLinearSystem D') :
    E + E' ∈ S.completeLinearSystem (D + D')

lemma add_mem_completeLinearSystem_left {D D' E E' : WeilDivisor X}
    (hE : E ∈ S.completeLinearSystem D) :
    E' ∈ S.completeLinearSystem D' → E + E' ∈ S.completeLinearSystem (D + D')

lemma add_mem_completeLinearSystem_right {D D' E E' : WeilDivisor X}
    (hE' : E' ∈ S.completeLinearSystem D') :
    E ∈ S.completeLinearSystem D → E + E' ∈ S.completeLinearSystem (D + D')

lemma sum_mem_completeLinearSystem (s : Finset ι) {D E : ι → WeilDivisor X}
    (h : ∀ i ∈ s, E i ∈ S.completeLinearSystem (D i)) :
    (∑ i ∈ s, E i) ∈ S.completeLinearSystem (∑ i ∈ s, D i)

lemma completeLinearSystem_eq_of_divisorClass_eq {D D' : WeilDivisor X}
    (h : S.divisorClass D = S.divisorClass D') :
    S.completeLinearSystem D = S.completeLinearSystem D'

lemma completeLinearSystem_eq_of_linearlyEquivalent {D D' : WeilDivisor X}
    (h : S.LinearlyEquivalent D D') :
    S.completeLinearSystem D = S.completeLinearSystem D'

lemma eq_zero_of_mem_completeLinearSystem_of_weightedDegree_zero {w : X → ℤ}
    (hw : ∀ x, 0 < w x) (h : S.IsWeightedDegreeZero w) {D E : WeilDivisor X}
    (hE : E ∈ S.completeLinearSystem D) (hD : weightedDegree w D = 0) : E = 0

def weightedDegreeZeroQuotientEquivPicZero (w : X → ℤ) (h : S.IsWeightedDegreeZero w) :
    weightedDegreeZeroSubgroup w ⧸ S.principalSubgroupOfWeightedDegreeZero w ≃+
      S.picZero w h

lemma IsWeightedDegreeZero.principalSubgroup_le_weightedDegree_ker {w : X → ℤ}
    (h : S.IsWeightedDegreeZero w) :
    S.principalSubgroup ≤ (weightedDegree w : WeilDivisor X →+ ℤ).ker

lemma coheight_eq_one_of_mem_support_toAlgebraicCycle (D : SchemeWeilDivisor X) {x : X}
    (hx : x ∈ (toAlgebraicCycle D).support) :
    coheight x = 1

lemma sup_eq_left {D : EffectiveDivisorOfDegree X d}
    {E : EffectiveDivisorOfDegree X e} :
    (sup D E : WeilDivisor X) = D ↔ (E : WeilDivisor X) ≤ D

lemma sup_eq_right {D : EffectiveDivisorOfDegree X d}
    {E : EffectiveDivisorOfDegree X e} :
    (sup D E : WeilDivisor X) = E ↔ (D : WeilDivisor X) ≤ E
